def format_invocation(name='', args=(), kwargs=None, **kw):
    repr_func = kw.pop('repr', repr)
    if kw:
        raise TypeError(f'unexpected kwargs: {kw!r}')
    if kwargs is None:
        kwargs = {}
    parts = [repr_func(a) for a in args]
    parts += [f'{k}={repr_func(v)}' for k, v in kwargs.items()]
    return f'{name}({", ".join(parts)})'
