def _format_t(path, root=T):
    if not path:
        return {T: 'T', S: 'S', A: 'A'}.get(root, 'T')
    root_str = {T: 'T', S: 'S', A: 'A'}.get(root, 'T')
    parts = [root_str]
    i = 0
    while i < len(path):
        op, arg = path[i], path[i + 1]
        if op == '.':
            parts.append(f'.{arg}')
        elif op == '[':
            if type(arg) is tuple and len(arg) == 2 and isinstance(arg[0], tuple) and isinstance(arg[1], dict):
                pass
            parts.append(f'[{_format_slice(arg)}]')
        elif op == 'P':
            parts.append(f'[{bbrepr(arg)}]')
        elif op == '(':
            args, kwargs = arg
            arg_parts = [bbrepr(a) for a in args]
            arg_parts += [f'{k}={bbrepr(v)}' for k, v in kwargs.items()]
            parts.append(f'({", ".join(arg_parts)})')
        elif op in ('x',):
            parts.append('.__star__()')
        elif op in ('X',):
            parts.append('.__starstar__()')
        elif op in ('+', '-', '*', '/', '%', ':', '&', '|', '^'):
            op_map = {'+': '+', '-': '-', '*': '*', '/': '/', '%': '%', ':': '**', '&': '&', '|': '|', '^': '^'}
            sym = op_map[op]
            rhs = bbrepr(arg)
            cur = ''.join(parts)
            parts = [f'({cur} {sym} {rhs})']
            i += 2
            continue
        elif op == '~':
            cur = ''.join(parts)
            parts = [f'(~{cur})']
            i += 2
            continue
        elif op == '_':
            cur = ''.join(parts)
            parts = [f'(-{cur})']
            i += 2
            continue
        i += 2
    return ''.join(parts)
